<?php
/**
 * TN Game Content Idea Generator
 * Turns Instagram intelligence signals into original TN Game content briefs and calendar-ready ideas.
 */
if (!defined('ABSPATH')) exit;

final class TNG_Content_Idea_Generator {
    private const ITEM='tng_social_item'; private const CANDIDATE='tng_social_candidate'; private const NONCE='tng_content_idea_nonce';
    public static function boot():void{static $b=false;if($b)return;$b=true;add_action('admin_menu',[__CLASS__,'admin_menu'],27);add_action('admin_post_tng_generate_content_idea',[__CLASS__,'generate']);add_action('admin_enqueue_scripts',[__CLASS__,'assets']);}
    public static function admin_menu():void{add_submenu_page('tng-content-studio','TN Game Idea Generator','Idea Generator','edit_posts','tng-content-idea-generator',[__CLASS__,'render']);}
    private static function records():array{return get_posts(['post_type'=>[self::ITEM,self::CANDIDATE],'post_status'=>['publish','draft','private'],'numberposts'=>500,'orderby'=>'date','order'=>'DESC']);}
    private static function meta(int $id,string ...$keys):string{foreach($keys as $key){$v=trim((string)get_post_meta($id,$key,true));if($v!=='')return $v;}return '';}
    private static function is_instagram(int $id):bool{$p=strtolower(self::meta($id,'_tng_candidate_platform'));if($p==='instagram')return true;$terms=get_the_terms($id,'tng_social_platform');if($terms&&!is_wp_error($terms)&&str_contains(strtolower((string)$terms[0]->name),'instagram'))return true;return str_contains(strtolower(self::meta($id,'_tng_candidate_source_url','_tng_source_url')),'instagram.com');}
    private static function score(int $id):int{return max(0,min(100,(int)self::meta($id,'_tng_candidate_trend_score','_tng_source_opportunity_score')));}
    private static function tags(int $id):array{$raw=self::meta($id,'_tng_candidate_hashtags','_tng_hashtags');preg_match_all('/#([\p{L}\p{N}_]+)/u',$raw,$m);$tags=$m[1]??[];if(!$tags&&$raw)$tags=preg_split('/[\s,]+/',$raw)?:[];return array_values(array_filter(array_unique(array_map(static fn($t)=>strtolower(trim((string)$t,"# \t\n\r\0\x0B")),$tags))));}
    private static function intelligence():array{$tags=[];$formats=[];$places=[];$creators=[];foreach(self::records() as $p){$id=(int)$p->ID;if(!self::is_instagram($id))continue;$score=self::score($id);foreach(self::tags($id) as $tag){if(!isset($tags[$tag]))$tags[$tag]=['count'=>0,'sum'=>0];$tags[$tag]['count']++;$tags[$tag]['sum']+=$score;}$format=strtolower(self::meta($id,'_tng_candidate_format','_tng_content_format'));if($format){if(!isset($formats[$format]))$formats[$format]=['count'=>0,'sum'=>0];$formats[$format]['count']++;$formats[$format]['sum']+=$score;}$place=self::meta($id,'_tng_candidate_location','_tng_location_name');if($place){$k=strtolower($place);if(!isset($places[$k]))$places[$k]=['label'=>$place,'count'=>0,'sum'=>0];$places[$k]['count']++;$places[$k]['sum']+=$score;}$creator=self::meta($id,'_tng_candidate_creator','_tng_creator_handle');if($creator){$creator='@'.ltrim($creator,'@');$k=strtolower($creator);if(!isset($creators[$k]))$creators[$k]=['label'=>$creator,'count'=>0,'sum'=>0];$creators[$k]['count']++;$creators[$k]['sum']+=$score;}}$rank=static function(array $rows):array{foreach($rows as &$r){$avg=$r['count']?(int)round($r['sum']/$r['count']):0;$r['signal']=(int)round($avg*.72+min(100,$r['count']*14)*.28);}unset($r);uasort($rows,static fn($a,$b)=>$b['signal']<=>$a['signal']);return $rows;};return ['tags'=>$rank($tags),'formats'=>$rank($formats),'places'=>$rank($places),'creators'=>$rank($creators)];}
    private static function first(array $rows,string $fallback=''):string{if(!$rows)return $fallback;$k=(string)array_key_first($rows);return (string)($rows[$k]['label']??$k);}
    private static function suggestions(array $intel):array{$place=self::first($intel['places'],'Tennessee');$format=self::first($intel['formats'],'reel');$tag=self::first($intel['tags'],'exploretennessee');$creator=self::first($intel['creators'],'');$fl=ucwords(str_replace('_',' ',$format));return [['title'=>'The 30-second reason to stop at '.$place,'hook'=>'You could drive right past this Tennessee stop — but here is why you should not.','angle'=>'Create an original '.$fl.' that quickly shows what makes '.$place.' worth adding to a TN Game trip. Lead with the strongest visual, then reveal one useful detail and end with a save-it-for-later prompt.','format'=>$format,'place'=>$place,'tag'=>$tag,'creator'=>$creator],['title'=>'Build a mini adventure around '.$place,'hook'=>'If you have a few hours in Tennessee, steal this adventure idea.','angle'=>'Turn the location signal into a practical mini itinerary: one main experience, one nearby local stop, and one bonus discovery. Connect the post naturally to Trip Mode without copying any source creator.','format'=>'carousel','place'=>$place,'tag'=>$tag,'creator'=>$creator],['title'=>'What people miss at '.$place,'hook'=>'Most people come for the obvious view. This is what they miss.','angle'=>'Use the recurring social interest around '.$place.' as the starting point for an original hidden-detail story. Feature a lesser-known fact, viewpoint, nearby stop, or game/checkpoint opportunity.','format'=>$format,'place'=>$place,'tag'=>$tag,'creator'=>$creator]];}
    public static function generate():void{if(!current_user_can('edit_posts'))wp_die('Not allowed.');check_admin_referer(self::NONCE);$title=sanitize_text_field(wp_unslash($_POST['idea_title']??''));$hook=sanitize_textarea_field(wp_unslash($_POST['idea_hook']??''));$angle=sanitize_textarea_field(wp_unslash($_POST['idea_angle']??''));$format=sanitize_key(wp_unslash($_POST['idea_format']??'reel'));$place=sanitize_text_field(wp_unslash($_POST['idea_place']??''));$tags=sanitize_text_field(wp_unslash($_POST['idea_hashtags']??''));$campaign=sanitize_text_field(wp_unslash($_POST['idea_campaign']??''));$planned=sanitize_text_field(wp_unslash($_POST['idea_date']??''));$next=sanitize_key(wp_unslash($_POST['next_step']??'edit'));if(!$title)$title='TN Game content idea';$id=wp_insert_post(['post_type'=>self::ITEM,'post_status'=>'draft','post_title'=>$title,'post_content'=>$angle]);if(is_wp_error($id))wp_die(esc_html($id->get_error_message()));foreach(['_tng_hook'=>$hook,'_tng_original_angle'=>$angle,'_tng_content_format'=>$format,'_tng_location_name'=>$place,'_tng_hashtags'=>$tags] as $k=>$v)update_post_meta($id,$k,$v);update_post_meta($id,'_tng_plan_status',$planned?'planned':'idea');if($campaign)update_post_meta($id,'_tng_campaign',$campaign);if($planned)update_post_meta($id,'_tng_planned_date',$planned);update_post_meta($id,'_tng_permission_status','not_needed');update_post_meta($id,'_tng_content_notes','Generated from aggregate TN Game Social Intelligence patterns. Create original media and copy; source posts are inspiration only.');if($next==='builder'){wp_safe_redirect(add_query_arg(['page'=>'tng-content-post-builder','idea'=>$id,'created'=>1],admin_url('admin.php')));exit;}wp_safe_redirect(admin_url('post.php?post='.(int)$id.'&action=edit&tng_idea_created=1'));exit;}
    public static function render():void{if(!current_user_can('edit_posts'))return;$intel=self::intelligence();$ideas=self::suggestions($intel);$topTag=self::first($intel['tags'],'—');$topPlace=self::first($intel['places'],'—');$topFormat=self::first($intel['formats'],'—');$topCreator=self::first($intel['creators'],'—');echo '<div class="wrap tng-cig"><section class="tng-cig-hero"><div><p class="eyebrow">CONTENT STUDIO</p><h1>Turn signals into original TN Game content.</h1><p>Use patterns from Instagram inspiration to create a fresh brief, then move it straight into production.</p></div><div class="hero-actions"><a class="button" href="'.esc_url(admin_url('admin.php?page=tng-social-intelligence-patterns')).'">View Intelligence</a><a class="button" href="'.esc_url(admin_url('admin.php?page=tng-content-post-builder')).'">Post Builder</a></div></section>';echo '<section class="tng-cig-signals">';foreach([['#'.$topTag,'Top hashtag'],[$topPlace,'Top place'],[ucwords(str_replace('_',' ',$topFormat)),'Top format'],[$topCreator,'Creator signal']] as $s)echo '<article><strong>'.esc_html($s[0]).'</strong><span>'.esc_html($s[1]).'</span></article>';echo '</section><div class="tng-cig-grid">';foreach($ideas as $i=>$idea){$hashtags='#'.ltrim($idea['tag'],'#').' #Tennessee #TheTNGame';echo '<form class="tng-cig-card" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE);echo '<input type="hidden" name="action" value="tng_generate_content_idea"><div class="tng-cig-num">0'.($i+1).'</div><label>CONTENT IDEA</label><input class="title" name="idea_title" value="'.esc_attr($idea['title']).'"><label>HOOK</label><textarea name="idea_hook" rows="3">'.esc_textarea($idea['hook']).'</textarea><label>ORIGINAL TN GAME ANGLE</label><textarea name="idea_angle" rows="5">'.esc_textarea($idea['angle']).'</textarea><div class="fields"><div><label>FORMAT</label><select name="idea_format">';foreach(['reel'=>'Reel','carousel'=>'Carousel','photo'=>'Photo','story'=>'Story','long_video'=>'Long video'] as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($idea['format'],$v,false).'>'.esc_html($l).'</option>';echo '</select></div><div><label>PLACE</label><input name="idea_place" value="'.esc_attr($idea['place']).'"></div></div><label>HASHTAGS</label><input name="idea_hashtags" value="'.esc_attr($hashtags).'"><div class="fields"><div><label>CAMPAIGN</label><input name="idea_campaign" placeholder="Coming Soon, Fall Trails…"></div><div><label>CONTENT CALENDAR DATE</label><input type="date" name="idea_date"></div></div><div class="tng-cig-actions"><button class="button" name="next_step" value="edit">Save idea</button><button class="button button-primary" name="next_step" value="builder">Create & build post →</button><small>Save it for later, or jump directly into the Post Builder.</small></div></form>';}echo '</div><section class="tng-cig-note"><strong>Originality guardrail</strong><p>This tool uses aggregate patterns — places, formats, hashtags, and performance signals — not copied captions or media. The saved brief is a starting point for original TN Game content.</p></section></div>';}
    public static function assets(string $hook):void{if(!isset($_GET['page'])||$_GET['page']!=='tng-content-idea-generator')return;wp_register_style('tng-content-idea-generator',false,[],defined('TNG_OS_VERSION')?TNG_OS_VERSION:null);wp_enqueue_style('tng-content-idea-generator');wp_add_inline_style('tng-content-idea-generator','.tng-cig{max-width:1220px}.tng-cig-hero{margin:20px 0;background:linear-gradient(135deg,#073c2b,#176b45);color:#fff;border-radius:24px;padding:32px;display:flex;justify-content:space-between;gap:30px;align-items:flex-start}.tng-cig-hero h1{color:#fff;font-size:34px;margin:5px 0 8px}.tng-cig-hero p{font-size:15px;max-width:720px}.hero-actions{display:flex;gap:8px;flex-wrap:wrap}.eyebrow,.tng-cig-card>label,.tng-cig-card .fields label{font-size:11px;font-weight:800;letter-spacing:.12em;color:#f05b25}.tng-cig-signals{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.tng-cig-signals article{background:#fff;border:1px solid #dde4df;border-radius:16px;padding:18px}.tng-cig-signals strong,.tng-cig-signals span{display:block}.tng-cig-signals strong{font-size:18px;color:#123527}.tng-cig-signals span{color:#68766f;margin-top:5px}.tng-cig-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.tng-cig-card{background:#fff;border:1px solid #dfe5e1;border-radius:20px;padding:22px;box-shadow:0 8px 24px rgba(17,54,39,.05)}.tng-cig-num{font-size:12px;font-weight:800;color:#799087;margin-bottom:12px}.tng-cig-card input,.tng-cig-card textarea,.tng-cig-card select{box-sizing:border-box;width:100%;margin:5px 0 14px;border:1px solid #d9e0dc;border-radius:9px;padding:10px}.tng-cig-card .title{font-size:20px;font-weight:700;color:#173629}.tng-cig-card textarea{resize:vertical}.tng-cig-card .fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.tng-cig-actions{border-top:1px solid #edf0ee;padding-top:14px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.tng-cig-actions small{display:block;width:100%;color:#718078;margin-top:2px}.tng-cig-note{margin:18px 0;background:#eef7f1;border:1px solid #cfe2d5;border-radius:16px;padding:18px;color:#254b39}.tng-cig-note p{margin:5px 0 0}@media(max-width:1000px){.tng-cig-grid{grid-template-columns:1fr}.tng-cig-signals{grid-template-columns:1fr 1fr}}');}
}
TNG_Content_Idea_Generator::boot();
